const r = await api.get("/customers");
const items = r.items;
const nov = items.filter(c => c.birth_date && (new Date(c.birth_date).getMonth() + 1) === 11);
const sample = items.slice(0,3).map(c => c.birth_date);
return { total: r.count, fetched: items.length, novCount: nov.length, sample };

const r = await api.get("/customers");
const nov = r.items.filter(c => c.birth_date && c.birth_date.split("-")[1] === "11");
return nov.map(c => ({ id: c.id, name: c.name, birth_date: c.birth_date }));

